def transform(grid):
    g = np.array(grid)
    bg = background(g)
    h, w = g.shape
    out = np.repeat(np.repeat(g, 2, axis=0), 2, axis=1)
    emit(out.copy(), "Scale the input by 2: every cell becomes a 2x2 block.")
    H, W = out.shape
    for y in range(h):
        for x in range(w):
            if g[y, x] == bg:
                continue
            # down-right ray from the block's bottom-right corner
            yy, xx = 2 * y + 2, 2 * x + 2
            while yy < H and xx < W:
                if out[yy, xx] == bg:
                    out[yy, xx] = 1
                yy += 1; xx += 1
            # up-left ray from the block's top-left corner
            yy, xx = 2 * y - 1, 2 * x - 1
            while yy >= 0 and xx >= 0:
                if out[yy, xx] == bg:
                    out[yy, xx] = 1
                yy -= 1; xx -= 1
            emit(out.copy(), f"Extend the main diagonal of the block from input cell ({y},{x}) with colour 1 in both directions to the grid edge.")
    emit(out.copy(), "Final grid: scaled blocks with their diagonal rays.")
    return out
